  speed0 = pedalSpeed; savedAction = actor+0x58; r = CheckRoll()
  if (r & FWD) { pedalSpeed = clamp(pedalSpeed + 0.17, -0.0, 2.0); pedalInterval.reset(); pedalInterval.start(0.13); return }
  if (r & BACK) { pedalSpeed = clamp(pedalSpeed - 0.3, -0.0, 2.0); pedalInterval.reset(); pedalInterval.start(0.13) }
  else if (r & STOP) { pedalSpeed = 0; CallAction(0x3755f434cb82713c ExActionStopPedal) }
  if (CheckFreelyOperation()) { pedalSpeed = speed0; CallAction(savedAction);
    if (!pedalFreely.active && !pedalInterval.active) { pedalFreely.start(0.13); pedalSpeed = clamp(pedalSpeed + 0.17, -0.0, 2.0); pedalInterval.reset(); pedalInterval.start(0.13) } }
clamp 순서: s = (s >= max) ? max : s; s = (s <= min) ? min : s (min = -0.0이라 결과 0 이상)
